package com.echoagent.sdk;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.security.MessageDigest;
class FileAuthorityIdentityHostTest {
 static final ObjectMapper JSON=new ObjectMapper();static final Path FIXTURE=Path.of("../shared/testing/file_authority_identity_fixture.py").toAbsolutePath();static final String HOST=System.getenv("ECHO_AGENT_SDK_HOST");
 static <T>T await(CompletionStage<T> value)throws Exception{return value.toCompletableFuture().get(15,TimeUnit.SECONDS);}
 static ObjectNode snapshot(Path work)throws Exception{var result=JSON.createObjectNode();for(String name:List.of("guarded.txt","original-backup.txt")){Path path=work.resolve(name);if(!Files.exists(path)){result.putNull(name);continue;}byte[] bytes=Files.readAllBytes(path);var row=result.putObject(name).put("sha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes))).put("base64",Base64.getEncoder().encodeToString(bytes)).put("byte_length",bytes.length);var stat=Files.readAttributes(path,java.nio.file.attribute.BasicFileAttributes.class);if(stat.fileKey()==null)throw new AssertionError("native file identity unavailable");row.put("device","java-basic-file-key").put("inode",stat.fileKey().toString());}return result;}
 static JsonNode call(SessionHandle session,Path work,ArrayNode rows,String id,String operation,List<?> args)throws Exception{var row=rows.addObject().put("id",id).put("operation","echo_core::utils::fs::"+operation);row.set("before",snapshot(work));var trace=row.putArray("arguments");for(Object arg:args){if(arg instanceof WireHandle handle)trace.add(handle.toJson());else trace.add(JSON.valueToTree(arg));}JsonNode value=null;try{value=await(session.invoke("echo_core::utils::fs::"+operation,args));row.set("value",value);}catch(ExecutionException failure){if(!(failure.getCause()instanceof EchoAgentException e))throw failure;var error=row.putObject("error").put("code",e.code()).put("message",e.getMessage()).put("operation",e.operation()).put("retryable",e.retryable());error.set("handle",e.handle()==null?NullNode.instance:e.handle().toJson());error.set("details",e.details()==null?NullNode.instance:e.details());}row.set("after",snapshot(work));return value;}
 @org.junit.jupiter.api.Test void sameLengthReplacementRejectsOldGuardBeforeWriting()throws Exception{
 if("1".equals(System.getenv("ECHO_AGENT_SDK_REQUIRE_HOST_E2E"))&&(HOST==null||HOST.isBlank()))throw new AssertionError("required FileAuthority Host missing");org.junit.jupiter.api.Assumptions.assumeTrue(HOST!=null&&!HOST.isBlank(),"real Host required");Path root=Path.of("../../target/file-authority-identity").toAbsolutePath().normalize();Files.createDirectories(root);Path work=Files.createTempDirectory(root,"java-");var prep=new ProcessBuilder("python3",FIXTURE.toString(),"--work",work.toString()).inheritIO().start();if(prep.waitFor()!=0)throw new AssertionError("fixture preparation failed");var spec=JSON.readTree(work.resolve("scenario.json").toFile());var rows=JSON.createArrayNode();
 try(var sdk=await(EchoAgentClient.spawn(HOST,List.of("--config",work.resolve("host.json").toString()),Path.of("../shared/facade-operation-catalog.json"),Path.of("../shared/contract-digests.json"),Map.of()))){var agent=await(sdk.createAgent());var session=await(agent.createSession(work.toString()));var path=WireValues.utf8Path(work.resolve("guarded.txt").toString());var guard=WireHandle.fromJson(call(session,work,rows,"open-original","open_existing_regular_guard",List.of(path)));call(session,work,rows,"length-original","matching_existing_regular_len",List.of(path,guard));call(session,work,rows,"append-original","append_existing_matching",List.of(path,guard,WireValues.u64(spec.path("initial_length").asText()),WireValues.bytes(new byte[]{'x'}),"sync_data"));call(session,work,rows,"length-appended","matching_existing_regular_len",List.of(path,guard));var before=snapshot(work);Files.move(work.resolve("guarded.txt"),work.resolve("original-backup.txt"));Files.write(work.resolve("replacement.tmp"),Base64.getDecoder().decode(spec.path("replacement_base64").asText()));Files.move(work.resolve("replacement.tmp"),work.resolve("guarded.txt"),StandardCopyOption.REPLACE_EXISTING);var swap=rows.addObject().put("id","replace-same-length");swap.set("before",before);swap.set("after",snapshot(work));call(session,work,rows,"stale-length","matching_existing_regular_len",List.of(path,guard));call(session,work,rows,"stale-append","append_existing_matching",List.of(path,guard,WireValues.u64(spec.path("replaced_length").asText()),WireValues.bytes(new byte[]{'b','a','d'}),"sync_data"));call(session,work,rows,"old-descriptor-length","ExistingRegularFileGuard::len",List.of(guard));var fresh=WireHandle.fromJson(call(session,work,rows,"open-replacement","open_existing_regular_guard",List.of(path)));call(session,work,rows,"length-replacement","matching_existing_regular_len",List.of(path,fresh));call(session,work,rows,"append-replacement","append_existing_matching",List.of(path,fresh,WireValues.u64(spec.path("replaced_length").asText()),WireValues.bytes(new byte[]{'z'}),"sync_data"));await(session.closeAsync());await(agent.closeAsync());}
 var data=JSON.createObjectNode().put("host",HOST).put("host_sha256",FileSha256.sha256(Path.of(HOST))).put("work",work.toString()).put("closed",true);data.set("rows",rows);JSON.writerWithDefaultPrettyPrinter().writeValue(work.resolve("results.json").toFile(),data);var verify=new ProcessBuilder("python3",FIXTURE.toString(),"--work",work.toString(),"--verify",work.resolve("results.json").toString()).redirectErrorStream(true).start();String output=new String(verify.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);System.out.println("FileAuthority identity: "+output+" evidence: "+work);if(verify.waitFor()!=0)throw new AssertionError("identity oracle failed: "+work);
 }
}
